// 自動生成（node docs/ui-guide/build.mjs）。手で編集しない。
window.SEARCH_INDEX = [{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n01","title":"01スクロール Scroll","text":"内容が枠より大きいとき、枠の中で表示位置を動かす。「枠（ビューポート）は動かず、中身が動く」。 操作：枠内でホイール／ドラッグ／ボタン。右の数値が scrollTop。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n02","title":"02パン Pan","text":"中身を「掴んで」平行移動する。スクロールと違い、境界がなく（無限に動かせる）、ドラッグ量＝移動量になる。地図・図面・キャンバスの基本操作。 操作：方眼をドラッグ。transform: translate() に差分を足すだけ。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n03","title":"03ズーム Zoom","text":"表示倍率を変える。ここでは「枠の中心」を基準に拡大縮小する最も単純な形。ホイール位置を基準にする本格版は 44。 操作：枠内でホイール（トラックパッドはピンチ＝ctrlKey 付き wheel）、またはボタン。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n04","title":"04クリック / タップ Click / Tap","text":"最も基本の操作だが、1回の操作で複数のイベントが順に発火する。マウスとタッチで順序・種類が違うことを見て覚える。 操作：青い箱をクリック／タップ。発火順がログに出る。pointer* を使えば入力装置を問わず1系統で書ける。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n05","title":"05ダブルクリック / 長押し Double click / Long press","text":"ダブルクリックは標準イベントがある。長押しは標準イベントが無いので「押してから一定時間、動かさずに離さない」をタイマーで判定する。 操作：左はダブルクリック。右は500ms押し続ける（動かすとキャンセル）。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n06","title":"06ホバー Hover","text":"ポインタが要素上にある状態。タッチ端末には「ホバー」が存在しないため、ホバーでしか出ない情報を作らない。 操作：箱にポインタを乗せる。@media (hover: hover) でホバー可能な環境か判定できる。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n07","title":"07フォーカス Focus","text":"キーボード入力を受け取る要素は常に1つ。Tabで順に移動する。:focus-visible はキーボード操作時だけ枠を出すので、マウス時に枠が邪魔にならない。 操作：最初のボタンを押した後 Tab / Shift+Tab。div は tabindex=\"0\" を付けて初めてフォーカスできる。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n08","title":"08ドラッグ&ドロップ Drag and Drop（HTML標準API）","text":"要素を掴んで別の場所へ移す。ここはブラウザ標準のDnD API版。見た目のゴーストはブラウザ任せで簡単だが、タッチ非対応・細かい制御不可。自作版は 32。 操作：左のカードを右へドラッグ。dragover で preventDefault() しないとドロップできない、が最大の罠。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n09","title":"09スワイプ / フリック Swipe / Flick","text":"指（ポインタ）を素早く払う操作。「移動距離」と「速度」の両方を見て判定する。距離だけだとゆっくりのドラッグと区別がつかない。 操作：灰色の帯を左右に素早く払う。マウスでもドラッグで再現できる。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n10","title":"10リサイズ Resize","text":"つまみ（ハンドル）をドラッグして大きさを変える。サイズ変化の検知は ResizeObserver が正解（window.resize は要素の変化を拾えない）。 操作：右下の角をドラッグ。最小サイズで止まる。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n11","title":"11選択 Select（単一 / Ctrl追加 / Shift範囲）","text":"項目を選ぶ。Excelやエクスプローラと同じ修飾キー慣習（Ctrl=追加/解除、Shift=範囲）に合わせると業務ユーザーは説明なしで使える。 操作：行をクリック。Ctrl/⌘ や Shift を押しながらクリック。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n12","title":"12フェードイン / フェードアウト Fade in / out","text":"不透明度（opacity）を時間で補間する。最も安価で自然な出現・消失。注意点は「opacity:0 でも要素はそこに在る（クリックできる）」こと。消した後は display:none か visibility:hidden にする。 操作：トグル。transitionend で「完全に消えた瞬間」を拾って非表示化している。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n13","title":"13スライドイン / スライドアウト Slide in / out","text":"画面端から滑り込む。left や margin ではなく transform を動かす（レイアウト計算が走らず滑らか）。ドロワー・サイドパネル・通知の基本。 操作：ボタンで右からパネルが出る。背景クリックでも閉じる。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n14","title":"14トランジション / イージング Transition / Easing","text":"状態AからBへ「時間をかけて」変える仕組みがトランジション。その途中の速度配分がイージング。UIでは ease-out（速く出て静かに止まる）が基本。ease-in は「反応が遅い」と感じさせる。 操作：ボタンで4つの玉を同時に走らせ、違いを見る。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n15","title":"15モーダル / ダイアログ Modal / Dialog","text":"背後の操作を止めて前面で確認・入力させる。標準の &lt;dialog&gt; を showModal() で開くと、背景の暗幕・Escで閉じる・フォーカス閉じ込め・背面の不活性化が全部ついてくる。 操作：開いて Esc や暗幕クリックで閉じる。戻り値は returnValue で受け取る。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n16","title":"16トースト / スナックバー Toast / Snackbar","text":"操作結果を隅に短時間表示し、自動で消える。作業を中断させない通知。読み上げ対応のため aria-live を付ける。 操作：連打すると積み上がる。ホバー中は消えない（読む時間を確保）。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n17","title":"17ツールチップ / ポップオーバー Tooltip / Popover","text":"補足情報を小さく浮かせて出す。難しいのは位置決め：画面端では上下・左右を反転させる。getBoundingClientRect() で対象の位置を取り、はみ出すなら反対側へ。 操作：ボタンにホバー／フォーカス。右端のボタンでは反転する。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n18","title":"18アコーディオン / 折りたたみ Accordion / Collapse","text":"セクションの開閉。height: auto へは CSS transition が効かない、が定番の壁。解決策は grid の 0fr → 1fr（JS不要・内容の高さを知らなくてよい）。 操作：見出しをクリック。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n19","title":"19タブ Tabs","text":"同じ領域を複数のビューで切り替える。WAI-ARIAの作法：タブ列は role=tablist、Tabキーでは選択中タブに止まり、←→ で隣へ移動。 操作：クリック、またはタブにフォーカスして矢印キー。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n20","title":"20ドロップダウン / メニュー Dropdown / Menu","text":"ボタン押下で選択肢を展開する。自作するときの必須処理は3つ：外側クリックで閉じる、Escで閉じる、項目選択で閉じる。 操作：ボタンを押し、外をクリックや Esc で閉じる。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n21","title":"21ページネーション / 無限スクロール Pagination / Infinite scroll","text":"大量データを分割して取得・表示する2方式。ページ番号は「位置が分かる」、無限スクロールは「操作が要らない」。kintoneのレコード取得（offset/limit、またはカーソルAPI）はこの下で動く。 操作：左は番号で切替。右は末尾までスクロールすると IntersectionObserver が「番兵」を検知して追加読み込みする。"},{"page":"02-basic.html","pageTitle":"第2弾 A：一般的なUI操作（01〜22）動くデモ","id":"n22","title":"22ローディング表示 Loading / Skeleton / Spinner","text":"待ち時間を可視化する。スピナーは「何か待っている」しか伝えないが、スケルトン（内容の形の灰色）は「何が来るか」を先に見せるので体感が速い。 操作：再読込で2秒待ち。どちらの待ち方が楽か比べる。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n23","title":"23仮想スクロール Virtual scroll / Windowing","text":"10万行あっても DOM は「見えている行＋少し」だけ作る。スクロール位置から開始行を割り算で求め、上に「行高×開始行」の余白を置いて位置を合わせる。 操作：スクロールしても DOM 行数は約20のまま。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n24","title":"24スティッキー（固定ヘッダー / 固定列） Sticky header / column","text":"スクロールしても見出しが留まる。position: sticky だけで実現でき、JSは不要。左上のセルは top と left の両方を指定して両方向に固定する。 操作：表を縦横にスクロール。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n25","title":"25スクロールスナップ Scroll snap","text":"スクロールを止めた時、区切り位置に吸着する。CSSだけで「カルーセル」「ページ単位の閲覧」ができ、慣性・タッチ対応もブラウザ任せ。 操作：横にスクロール（Shift+ホイール or トラックパッド）。どこで止めてもカードの先頭に揃う。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n26","title":"26パララックス Parallax","text":"前景と背景を異なる速度で動かして奥行きを出す。実装は「スクロール量 × 係数」を transform に入れるだけ。業務アプリでは酔いやすいので控えめに。 操作：枠内をスクロール。背景の丸は 0.3 倍の速度で動く。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n27","title":"27スクロール連動アニメーション Scroll-driven reveal","text":"要素が画面に入った瞬間をトリガーにする。scroll イベントで毎回位置計算せず、IntersectionObserver に「入った／出た」だけ教えてもらう。 操作：枠内をスクロール。入ったカードがフェード＋上昇で現れる。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n28","title":"28慣性 / モーメンタム Inertia / Momentum","text":"指を離した後も速度を保ちながら減速して止まる。「離した瞬間の速度」を記録し、毎フレーム速度に減衰係数（0.95など）を掛けて位置を進める。パン（02）にこれを足すと「気持ちよさ」が出る。 操作：方眼を素早くドラッグして離す。壁で跳ね返る。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n29","title":"29スプリング物理 Spring animation","text":"目標との差に比例した力（バネ）と速度に比例した抵抗（減衰）で動かす。時間固定のトランジションと違い、途中で目標が変わっても不自然にならない。 操作：枠内をクリック。連続でクリックして途中変更の滑らかさを見る。剛性・減衰を変えてみる。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n30","title":"30FLIPアニメーション First-Last-Invert-Play","text":"レイアウトが変わる（並べ替え・追加・削除）ときの定石。①変更前の位置を測る（First）②DOMを変える③変更後の位置を測る（Last）④差分だけ transform で元の位置に戻す（Invert）⑤transformを0へアニメーション（Play）。 操作：シャッフル。DOMは一瞬で並び替わっているが、見た目は滑らかに移動する。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n31","title":"31ビュー遷移 View Transitions API","text":"DOM更新の「前」と「後」をブラウザがスナップショットし、自動でクロスフェードする。view-transition-name を付けた要素は位置・サイズの移動もアニメーションする。未対応ブラウザでは即時切替にフォールバック。 操作：「一覧」と「詳細」を切り替える。画像だけは同じ名前を持つので位置が繋がる。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n32","title":"32ドラッグ並べ替え Sortable / Reorder（Pointer Events自作）","text":"HTML標準DnD（08）を使わず Pointer Events で自作すると、タッチ対応・見た目の完全制御・FLIPとの併用ができる。掴んだ要素は transform で追従させ、他要素との重なりで挿入位置を決める。 操作：行をドラッグして並べ替え。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n33","title":"33分割パネル / ドッキング Split pane / Dock layout","text":"境界（ガター）をドラッグして領域比率を変える。IDE風レイアウトの基礎。grid の列幅を書き換えるだけで、中身のレイアウトは自動で追従する。慣習：最小幅で止まる、ガターのダブルクリックで初期比率に戻す。 操作：中央の縦棒をドラッグ。ダブルクリックでリセット。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n34","title":"34キーボードナビゲーション Roving tabindex","text":"ツールバーやグリッドの中は矢印キーで移動し、Tab は「グループごと」に抜ける。実現方法は「今の項目だけ tabindex=0、他は -1」に付け替え続けること（roving = 巡回）。 操作：最初のボタンにフォーカス（クリック）→ ←→HomeEnd。Tab で次のグループへ一気に抜ける。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n35","title":"35ショートカットキー Hotkeys","text":"キー組合せで機能を呼ぶ。要点：①ブラウザ既定動作を preventDefault() で止める ②入力欄にフォーカス中は単独キーのショートカットを無効化 ③Mac は metaKey、Windows は ctrlKey。 操作：このページ上で Ctrl/⌘+S、Ctrl/⌘+K（36へ）、単独 N。入力欄内で N を打つと無視される。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n36","title":"36コマンドパレット Command palette","text":"Ctrl+K で検索窓を開き、機能を文字で呼び出す。あいまい検索 → 矢印で選択 → Enter で実行。機能が増えてもメニューを掘らずに済む。 操作：ボタンか Ctrl/⌘+K。「csv」「削」などで絞り込み。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n37","title":"37アンドゥ / リドゥ Undo / Redo","text":"操作履歴を積んで巻き戻す。ここは「状態のスナップショット」方式（過去の状態を丸ごと配列に保存）。単純で確実。状態が大きいなら「逆操作コマンド」方式を検討する。 操作：丸を追加／色替え → Ctrl/⌘+Z / Ctrl/⌘+Shift+Z またはボタン。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n38","title":"38インライン編集 Inline editing","text":"表示中の値をその場で編集状態に切り替える。終了経路を3つ揃える：Enter=確定、Esc=取消、フォーカスが外れた=確定。どれか欠けると「戻れない」UIになる。 操作：セルをダブルクリック（またはフォーカスして Enter）。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n39","title":"39カスタムコンテキストメニュー Custom context menu","text":"右クリックで独自メニューを出す。contextmenu イベントを止め、クリック位置に出す。画面端では反転して枠内に収める。 操作：灰色の領域で右クリック（タッチは長押し）。端の方で試す。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n40","title":"40進捗表示 Progress（determinate / indeterminate）","text":"完了率が分かるなら確定型（バー）、分からないなら不定型（流れるだけ）。長い処理には必ずキャンセル手段を添える。AbortController で中断できる作りにしておく。 操作：開始 → 途中でキャンセル。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n41","title":"41ジェスチャー競合の解決 touch-action / 方向ロック","text":"「縦にスクロールしたいのか、横にスワイプしたいのか」をブラウザと取り合わない。touch-action: pan-y で縦はブラウザに任せ、横は自分で取る。さらに初動数pxの方向で「今回はどちらか」を確定（方向ロック）する。 操作：カードを横にドラッグ（削除アクションが出る）。縦に動かすと枠がスクロールする。タッチ端末で差がよく分かる。"},{"page":"03-custom.html","pageTitle":"第2弾 B：カスタマイズ性の高いUI（23〜42）動くデモ","id":"n42","title":"42モーション低減対応 prefers-reduced-motion","text":"OS設定で「視覚効果を減らす」を選んだユーザーには、動きを短縮・省略する。CSSのメディアクエリ1つで全アニメーションを止められる。JSからも matchMedia で判定できる。 操作：ボタンで動かす。OS設定を変えるとこのページの動きが止まる（右の表示で確認）。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n43","title":"43無限キャンバス Infinite canvas（パン＋ズーム＋座標変換）","text":"画面座標（ピクセル）とワールド座標（図面上の位置）を分けて持つ。表示は screen = world × scale + offset、入力は逆算 world = (screen − offset) ÷ scale。この2つの式だけで、パン・ズーム・クリック位置の特定が全部つながる。 操作：ドラッグでパン、ホイールでズーム（カーソル基準）、ダブルクリックでその位置に点を置く。右上にカーソルのワールド座標が出る。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n44","title":"44ズーム中心の維持 Zoom-to-cursor","text":"「ズームすると見ていた場所がズレる」の正体は、原点基準で scale しているから。カーソル下のワールド座標を先に求め、scale 変更後も同じ点がカーソル下に来るよう offset を計算し直す。式：offset = cursor − world × newScale。 操作：方式を切り替えて、同じ位置でホイールしてみる。「原点基準」だと図がカーソルから逃げる。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n45","title":"45ミニマップ Minimap","text":"全体を縮小して描き、現在の表示範囲を枠で示す。枠のドラッグでも移動できる。同じワールド座標を「別の縮尺」で描いているだけなので、43 の式がそのまま使える。 操作：大きい方をドラッグでパン、または右下のミニマップの枠をドラッグ。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n46","title":"46ノードエディタ Node graph / Wiring","text":"ノード（箱）のポート同士を線で結ぶ。線は SVG のベジェ曲線 M x1 y1 C x1+d y1, x2−d y2, x2 y2。出力ポートからドラッグ→入力ポートで離すと接続。ノードを動かすと線を引き直す。 操作：右側の●から左側の●へドラッグして接続。ノード本体をドラッグで移動。線をクリックで削除。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n47","title":"47スナップ / スマートガイド Snapping / Smart guides","text":"ドラッグ中、他要素の端・中心と一定距離（しきい値）以内なら、その座標に吸着してガイド線を出す。候補座標を全部列挙して「最も近いものが閾値内か」を見るだけ。 操作：青い箱をドラッグして灰色の箱の端・中心に近づける。Ctrl を押しながらだとスナップ無効。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n48","title":"48矩形選択 Rubber band selection","text":"空白からドラッグして矩形を描き、重なった要素をまとめて選ぶ。判定は「矩形同士が交差するか」の4比較。Shift 併用で既存選択に追加。 操作：空白からドラッグ。Shift+ドラッグで追加選択。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n49","title":"49ポインタキャプチャ setPointerCapture","text":"ドラッグ中にポインタが要素の外に出ても、その要素がイベントを受け続けるようにする。これが無いと「速く動かすと箱が置いていかれる」「外で離すと pointerup が来ない」が起きる。 操作：2つの箱を素早くドラッグして比べる。左はキャプチャなし（外に出た瞬間止まる）。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n50","title":"50マルチタッチジェスチャー Pinch / Rotate / 2-finger pan","text":"2本の指の「距離」「角度」「中点」の変化量から、拡大率・回転角・移動量を同時に求める。pointerId ごとに座標を Map で持てば、Pointer Events だけで書ける。 操作：タッチ端末なら2本指でピンチ／回転。マウスなら Shift を押しながらドラッグすると「2本目の指が箱の中心に固定されている」扱いで模擬できる。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n51","title":"51修飾キーによる制約 Constrained drag（Shift / Alt / Ctrl）","text":"ツール系アプリの共通作法：Shift=軸固定（水平か垂直のみ）、Alt=グリッド吸着、Ctrl=吸着解除。移動量の計算の最後に、押されているキーで補正を掛けるだけ。 操作：箱をドラッグしながら Shift / Alt を押す。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n52","title":"52状態機械駆動UI State-machine driven interaction","text":"「押した」「動かした」「離した」を場当たり的に処理するとバグが出る。状態を明示（idle → pressed → dragging → idle）し、各イベントで「今の状態で何が起きたら次はどこか」だけを書く。押しただけ（pressed→idle）はクリック、閾値を超えたらドラッグ、と分岐が自然に決まる。 操作：箱をクリック／少しだけ動かす／大きく動かす。右の図で現在状態が光る。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n53","title":"53Web Animations API WAAPI","text":"JS からアニメーションを生成し、一時停止・逆再生・速度変更・完了待ち（Promise）ができる。CSS transition では「途中で止めて戻す」が書きにくいが、WAAPI なら animation.reverse() の1行。 操作：ボタンで制御。「完了待ち」は await anim.finished の後にログが出る。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n54","title":"54描画ループ最適化 rAF batching","text":"pointermove は 1フレームに複数回来ることがある（高レートマウス・タッチ）。イベントごとに描画すると無駄。「最新の値だけ保存し、描画は requestAnimationFrame で1フレーム1回」にまとめる。 操作：方眼の上でマウスを素早く動かす。イベント回数と描画回数の差を見る。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n55","title":"55Canvas 描画 Canvas rendering + ヒットテスト + devicePixelRatio","text":"DOM要素を数万個作ると重いが、Canvas ならビットマップに描くだけなので軽い。代わりに「どれをクリックしたか」は自分で計算する（ヒットテスト）。高解像度画面では devicePixelRatio 分だけ内部解像度を上げないとぼやける。 操作：点の上にマウスを乗せると赤くなる（距離計算でヒット判定）。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n56","title":"56データグリッド操作 セル範囲選択 / 列幅変更 / フィルハンドル / 貼り付け","text":"業務アプリの中核。Excel の作法をどこまで再現するかで使い勝手が決まる。ここでは4つ：①ドラッグでセル範囲選択 ②列見出しの境界ドラッグで列幅変更 ③選択範囲右下の■を下にドラッグで値を埋める ④Excelからコピーした表を Ctrl+V で流し込む（TSV解析）。 操作：セルをドラッグ、列境界をドラッグ、右下■を下へドラッグ、Excel等の表をコピーしてグリッド上で貼り付け。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n57","title":"57楽観的更新 Optimistic UI","text":"サーバ応答を待たずに画面を先に更新し、失敗したら元に戻す。kintone の PUT /k/v1/record.json のような更新系で、体感の遅さを消す。ロールバックとエラー通知が必須。 操作：チェックを切り替える（即反映）。「失敗させる」をONにすると 1.2秒後に巻き戻る。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n58","title":"58フォーカス管理 / ライブリージョン Focus trap / inert / aria-live","text":"自作モーダルでは3つ必要：①開いたら中にフォーカスを移す ②背面を inert にして Tab が抜けないようにする ③閉じたら元の要素へフォーカスを戻す。非同期の結果は aria-live 領域に書くと読み上げソフトが通知する。 操作：開いて Tab を連打（外に出ない）→ 閉じると「開く」ボタンにフォーカスが戻る。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n59","title":"59ファイルドロップ File drop / DataTransfer","text":"OSのエクスプローラからファイルをドラッグして受け取る。dragover で preventDefault() しないとブラウザがファイルを開いてしまう。ドロップ領域のハイライトと、種別・サイズの検証をここで行う。 操作：デスクトップからファイルを枠に落とす（クリックで選択も可）。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n60","title":"60コンテナクエリ Container queries","text":"画面幅ではなく「自分が置かれた枠の幅」でレイアウトを切り替える。同じカード部品を、広いメイン領域では横並び、狭いサイドパネルでは縦積みにできる。ドッキングレイアウト（33）の中身に必須。 操作：枠の右下をドラッグして幅を変える。420px を境にカード内のレイアウトが変わる。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n61","title":"61Electron：フレームレスウィンドウの操作 -webkit-app-region","text":"OS標準のタイトルバーを消して自前のヘッダーを作る場合、「ここを掴んだらウィンドウごと動く」領域を CSS で宣言する。ボタンなど押したい要素は no-drag で除外しないとクリックできなくなる。ブラウザでは効かないため、ここでは同じCSSを当てたモック（枠内でウィンドウを動かす模擬）を置いている。 操作：模擬ウィンドウのタイトルバーをドラッグ（Electron では本物のウィンドウが動く）。ボタン部分は掴めない。"},{"page":"04-pro.html","pageTitle":"第2弾 C：プロ志向のUI（43〜62）動くデモ","id":"n62","title":"62Electron：ネイティブメニュー / ショートカット Menu / accelerator / IPC","text":"OSのメニューバー（ファイル・編集…）とショートカットはメインプロセスで定義し、押されたら IPC で renderer に通知する。renderer 側は「メニューから来た」「ボタンから来た」を区別せず同じ関数を呼ぶ設計にする。ブラウザでは動かないため、下のボタンで「メニューが押された通知が来た」状況を模擬している。 操作：「メニュー: 新規作成 を模擬」を押すと、renderer の受信ハンドラが動く。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n71","title":"71大規模グリッドの複合 仮想スクロール＋固定列＋列並べ替え＋範囲コピー","text":"数千〜数万行を扱う一覧の完成形。①行は仮想化（23）②先頭列は固定（24）③見出しをドラッグで列順変更（32の応用）④セル範囲をドラッグ選択して Ctrl+C でTSVとしてコピー（Excelにそのまま貼れる）。データは列順とは独立に保持し、表示時に「列順の配列」を通して並べる。 操作：スクロール／見出しをドラッグして列を入れ替え／セルをドラッグ選択して Ctrl+C。コピー内容は下に表示。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n74","title":"74検索の型 インクリメンタル / デバウンス / ハイライト / あいまい検索","text":"入力のたびに検索するが、①デバウンス（打鍵が止まって250ms後に実行）で無駄な処理を省き、②一致箇所を &lt;mark&gt; で強調し、③あいまい検索は「文字が順番に現れるか」をスコア化して並べる（先頭一致・連続一致を高得点に）。kintone API へ投げる場合もデバウンスは必須。 操作：「部品12」「p12鈴」「高橋 倉庫」などを入力。「p12鈴」は部分一致では0件、あいまいでは「P-0012 部品12 鈴木…」が上位に来る。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n75","title":"75フォームの型 ステッパー / 条件分岐 / 途中保存 / 離脱警告","text":"長い入力を①段階に分け（ステッパー）②回答に応じて項目を出し分け（条件分岐）③入力のたびに下書きを保存し（localStorage）④未保存のまま離れようとしたら警告する（beforeunload）。状態は「1つのオブジェクト」に集約し、画面はそれを描画するだけにすると分岐が破綻しない。 操作：入力して次へ。「分納あり」を選ぶと項目が増える。ページを再読込しても下書きが復元される。入力途中でタブを閉じようとすると警告が出る。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n76","title":"76バッチ操作UI 複数選択 → 一括変更 → プレビュー → 確定 → 進捗と部分失敗","text":"一括更新は「取り消しにくい」ので、確定前にプレビュー（何が何に変わるか）を必ず見せる。実行中は進捗を出し、一部失敗しても止めずに完走させ、最後に「失敗分だけ再試行」を提供する。kintone の PUT /k/v1/records.json（100件上限）に合わせてチャンク分割する形。 操作：行をチェック → ステータスを選ぶ → プレビュー → 実行。約20%が失敗するので再試行を試す。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n77","title":"77差分表示 変更前後のハイライト / 変更履歴の切替","text":"レコードの版（リビジョン）を並べ、①項目単位で「変更あり」を色分けし、②長文は単語単位の差分（LCS）で削除・追加を示す。kintone の変更履歴を「何がどう変わったか」まで見せる形。差分アルゴリズムは単語配列のLCSで十分（数百語規模なら瞬時）。 操作：比較する版を左右で選ぶ。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n80","title":"80ドッキングレイアウト完成形 タブ移動 / 分割リサイズ / 分離（フローティング） / レイアウト保存","text":"IDE風の骨格。「パネル（内容）」と「ゾーン（置き場所）」を分けて考え、レイアウト状態を1つのJSONで持つ：{ zones: { left:[...], center:[...], right:[...] }, float:[...], widths:[...] }。描画はこのJSONから毎回組み立て直す。保存・復元はJSONを localStorage に入れるだけ。 操作：タブを別ゾーンへドラッグ／境界をドラッグ／タブの「⧉」で分離、フローティングの「⊡」で戻す／「保存」→再読込で復元。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n81","title":"81ワークスペース永続化 画面状態の保存と復元","text":"「どのタブを開いていたか」「どこまでスクロールしていたか」「何を選んでいたか」「絞り込み条件」を1つのオブジェクトにまとめ、変更のたびに（デバウンスして）保存する。起動時にそれを読み、描画してから scrollTop を戻す。ユーザーは「昨日の続き」から始められる。 操作：タブ・絞り込み・選択・スクロールを変えてからページを再読込（F5）。同じ状態に戻る。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n85","title":"85マルチウィンドウ同期 BroadcastChannel / Electron IPC","text":"同じアプリを複数ウィンドウ（タブ）で開いたとき、片方の変更をもう片方へ即時に反映する。ブラウザ／Electron renderer 同士なら BroadcastChannel が最も簡単（同一オリジン内で全ウィンドウに届く）。Electron でメインプロセスが「真実の状態」を持つ設計なら、IPC で全ウィンドウへ配信する。 操作：「別ウィンドウで開く」でこのページをもう1つ開き、片方でカウンタや選択を変えると、もう片方に即反映される。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n72","title":"72ツリー / 階層グリッド Tree grid with virtual scroll","text":"部品表（BOM）や組織のような階層を、展開状態を持ったまま仮想スクロールする。コツは「木」をそのまま描かず、展開中のノードだけを平坦な配列に変換してから 23 の仮想スクロールに渡すこと。展開／折りたたみは平坦化をやり直すだけ。 操作：▶ で展開。全展開（2,440ノード）しても DOM 行数は増えない。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n73","title":"73ピボット集計ビュー Pivot with drag-to-assign axes","text":"レコード一覧を「行の軸」「列の軸」「集計値」に振り分けて集計表を作る。項目チップを枠へドラッグして軸を組み替える。集計は Map に「行キー｜列キー」で足し込むだけ。kintone のレコードを取得した後の分析ビューとして使える。 操作：チップを「行」「列」の枠へドラッグ（HTML標準DnD）。「値」は数量/金額を切替。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n78","title":"78競合解決 Conflict resolution（楽観ロック）","text":"自分が編集している間に他の人が同じレコードを更新していたら、保存時に検知して「上書き／マージ／破棄」を選ばせる。検知はリビジョン番号で行う（kintone は revision を持ち、不一致なら PUT が失敗する）。3方向比較（元・自分・相手）で、片方しか変えていない項目は自動マージできる。 操作：「他ユーザーが更新」を押してから保存すると競合ダイアログが出る。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n79","title":"79オフライン対応 Offline queue and sync status","text":"通信できない間の操作をキューに溜め、復帰したら順に再送する。画面には「未同期 n 件」を常に見せ、ユーザーが不安にならないようにする。判定は navigator.onLine と online/offline イベント、ただし「繋がっているがAPIが落ちている」も同じ扱いにする（送信失敗→キューに戻す）。 操作：「オフライン」にして操作を数回 → 「オンライン」に戻すとキューが流れる。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n82","title":"82ルーティングと履歴 History API / 戻る・進むで状態復元","text":"SPA でも「戻る」ボタンが効くように、画面遷移を history.pushState で履歴に積む。state オブジェクトにスクロール位置や絞り込みを入れておけば、popstate で戻ったときにその状態ごと復元できる。Electron でも同じ仕組みが使える。 操作：絞り込み→スクロール→行をクリックで詳細へ→ブラウザの「戻る」（または枠内の←）。一覧が同じ位置・同じ絞り込みで戻る。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n83","title":"83スマートプレビュー Hover prefetch and preview card","text":"リンクにホバーして一定時間（300ms）留まったら、先読みしてカードで内容を出す。カーソルが通り過ぎただけでは取得しない（遅延＋キャンセル）。取得結果はキャッシュし、2回目は即表示。kintone なら GET /k/v1/record.json をここで叩く。 操作：リンクにホバーして少し待つ。同じリンクに戻ると即表示（キャッシュ）。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n84","title":"84ズーム可能タイムライン / ガント Time axis with pan, zoom, drag","text":"43 の座標変換を「横軸＝時間」に適用したもの。x = (t − t0) × pxPerDay + offset と逆変換だけで、パン・ズーム・バーのドラッグ（日付変更）・日単位スナップが全部書ける。目盛りはズーム倍率に応じて「日／週／月」を切り替える。 操作：背景ドラッグでパン、ホイールでズーム（カーソル基準）、バーをドラッグで日程変更（日単位に吸着）。"},{"page":"05-advanced.html","pageTitle":"第3弾 D：業務アプリの上位UI（71〜85 抜粋）動くデモ","id":"n86","title":"86監視ボード型UI Polling / 変化点のフラッシュ / 通知集約","text":"現場の状況を常時表示する画面。①一定間隔で取得（タブが隠れている間は止める：visibilitychange）②前回との差分だけをフラッシュ表示 ③通知は1件ずつ出さず「n件更新」に集約し、ミュートできる。ポーリング間隔は「取得にかかった時間」より十分長くする。 操作：2秒ごとに値が変わり、変わったセルが光る。タブを切り替えると停止し、戻ると再開する。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n63","title":"63シェアードエレメント遷移 Shared element transition","text":"一覧の行が「同じ物として」詳細画面へ拡大移動する。View Transitions（31）で、遷移する瞬間だけクリックした要素に view-transition-name を付ける。全行に同じ名前を付けると衝突して失敗するので、動的に付け外しするのが要点。 操作：カードをクリック→詳細へ。「戻る」で逆再生。非対応ブラウザは即時切替。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n64","title":"64スタガーアニメーション Stagger","text":"複数要素を数十msずつ遅らせて順に出す。「一斉にドン」より軽く見え、視線を上から下へ誘導できる。CSSなら animation-delay: calc(var(--i) * 40ms)、JSなら WAAPI の delay。要素数が多いときは合計時間が伸びすぎないよう上限を設ける。 操作：再生。間隔を変えて印象の違いを見る。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n65","title":"65スケルトン → 実データのモーフィング Skeleton morph","text":"スケルトン（22）から本物の内容へ切り替わる瞬間に「ガタつき」が出るのを防ぐ。①スケルトンと本物を同じ位置に重ね、クロスフェードする ②高さが変わるならFLIP（30）の高さ版で滑らかに伸縮する。 操作：再読込。「ガタつき版」と比べる。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n66","title":"66マイクロインタラクション Micro-interactions","text":"操作に対する「小さな返事」。チェックのバウンス、保存ボタンの「送信中→完了」の形状変化、いいねの弾み。ルール：150〜300ms、ユーザーの操作の直後に、操作したその場所で起きる。装飾ではなく「受け付けた」の合図。 操作：それぞれ押す。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n67","title":"67ジェスチャー連動の物理 Interactive back swipe","text":"画面遷移を「アニメーション再生」ではなく「指の位置に追従」させ、離した時点で完了か取消かを決める（iOSの戻る操作）。ドラッグ量を0〜1の進捗に変換し、離したら閾値（40%）と速度で判定、残りはスプリング（29）で流す。 操作：詳細画面の左端からドラッグ。途中で戻すとキャンセルされる。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n68","title":"68スクロール駆動アニメーション（CSS） animation-timeline: scroll() / view()","text":"27 は JS（IntersectionObserver）だったが、CSS だけで「スクロール量＝アニメーション進捗」にできる。scroll() はスクロール位置に、view() は要素が見えている割合に連動する。メインスレッドを使わないので滑らか。非対応ブラウザでは単に表示される（プログレッシブ）。 操作：枠内をスクロール。上端の読了バーと、各カードの出現がスクロールに同期する。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n69","title":"69ぼかし / グラスモーフィズム backdrop-filter と性能","text":"半透明パネルの背後をぼかす backdrop-filter: blur()。見栄えは良いが、背後が動くたびに毎フレーム再計算されるためGPUが弱い端末では重い。実機で計測し、必要なら blur を外して単なる半透明にする。 操作：ぼかしON/OFFを切り替えて、右上のフレーム時間を比べる（差が出ない端末なら採用してよい）。"},{"page":"06-effects.html","pageTitle":"第4弾 E：演出・体感の上位効果（63〜70）動くデモ","id":"n70","title":"70ダークモード切替のクロスフェード Theme transition with View Transitions","text":"テーマ切替時に全画面がパッと変わるのを、View Transitions で滑らかにする。標準は全体クロスフェード。::view-transition-new(root) に clip-path: circle() をアニメーションさせると「クリック位置から広がる」演出になる。テーマ自体は data-theme 属性と CSS 変数で。 操作：ボタンを押す（押した位置から広がる）。このデモ枠内だけがテーマ切替の対象。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f1","title":"F1座標系の違い clientX / pageX / offsetX / screenX / getBoundingClientRect","text":"マウス位置には5種類の「原点」がある。ドラッグやズームで一番よく使うのは clientX と getBoundingClientRect().left の差（＝要素内のローカル座標）。offsetX は「イベントが当たった要素」基準なので、子要素の上で値が飛ぶ。 操作：枠内でマウスを動かす。枠は少しスクロールしてある。青い子要素の上で offsetX がどう変わるか見る。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f2","title":"F2イベントの発火順と伝播 capture → target → bubble / stopPropagation","text":"イベントは「外側から内側へ（capture）→ 当たった要素（target）→ 内側から外側へ（bubble）」の順に流れる。addEventListener(type, fn, true) で capture 側に登録できる。stopPropagation() はそこから先へ流さない。preventDefault() は伝播ではなく「ブラウザの既定動作」を止める。この2つの違いが最重要。 操作：内側の箱をクリック。ログに順序が出る。チェックで「中央で stopPropagation」を有効にすると、外側の bubble が来なくなる。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f3","title":"F3transform と left/top の違い レイアウト vs 合成","text":"位置を動かす方法は2つあるが、コストが違う。left/top を変えるとブラウザはレイアウト計算（周囲の要素の位置も再計算）をやり直す。transform は最終的な合成段階で動かすだけで、レイアウトは走らない。だからデモは全部 transform で動かしている。opacity も同じく安い。 操作：300個の箱を同じ動きで走らせ、フレーム時間を比べる。差が小さい端末もあるが、要素数が増えるほど開く。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f4","title":"F4passive リスナーと touch-action スクロールを止めたいのに止まらない理由","text":"ブラウザは wheel / touchmove を「既定で passive（preventDefault が効かない）」として扱うことがある。自前でズームやパンをするなら { passive: false } を明示する。タッチでは加えて CSS の touch-action で「どの方向をブラウザに任せるか」を宣言する方が確実。 操作：左右の枠でホイール。左は preventDefault が無視されてページがスクロールする。右は止まる。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f5","title":"F5動かし方の4手段 transition / CSS animation / WAAPI / requestAnimationFrame","text":"同じ「右に300px動かす」でも手段が4つある。使い分けの軸は「誰が時間を管理するか」と「途中で介入したいか」。迷ったら transition、JSで止めたり戻したりするなら WAAPI、毎フレーム値を計算するなら rAF。 操作：再生。4つが同じ動きをするのを確認し、下の表で選び方を見る。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f6","title":"F6スロットルとデバウンス Throttle / Debounce","text":"高頻度イベント（scroll, pointermove, input, resize）の間引き方は2種類。デバウンス＝止まってから1回（検索、保存）。スロットル＝一定間隔で1回（スクロール連動、進捗表示）。描画目的なら 54 の rAF バッチが第3の選択肢。 操作：灰色の帯でマウスを動かす。3つのカウンタの増え方を比べる。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f7","title":"F7重なり順とスタッキングコンテキスト z-index が効かない理由","text":"z-index は「同じスタッキングコンテキスト内」でしか比較されない。親に transform・opacity&lt;1・filter・position + z-index などがあると、そこで新しいコンテキストができ、子の z-index がいくら大きくても親の外の要素を追い越せない。ツールチップやドロップダウンが「下に潜る」原因の9割はこれ。 操作：チェックで左の親に transform を付ける。子の z-index:999 が右の z-index:1 に負ける。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f9","title":"F9レイアウトスラッシング 読み取りと書き込みを交互にすると遅くなる","text":"DOM の「幅を読む（offsetWidth, getBoundingClientRect）」と「スタイルを書く」を1要素ずつ交互にやると、ブラウザは書くたびにレイアウトをやり直してから読む（強制同期レイアウト）。先に全部読んでから、全部書くだけで桁違いに速くなる。FLIP（30）の「First を全部測ってから DOM を変える」もこの原則。 操作：500要素で2つの方式を実行し、時間を比べる。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f10","title":"F10計測の道具 performance.now / PerformanceObserver(longtask) / rAF フレーム時間","text":"「重い気がする」を数字にする3つの道具。①performance.now() で区間時間 ②PerformanceObserver の longtask で 50ms を超えてメインスレッドを塞いだ処理を検出 ③rAF の間隔でフレーム落ちを見る。開発者ツールの Performance タブが本命だが、実機で常時出しておくならこれ。 操作：「重い処理を実行」で意図的に 120ms ブロックする。longtask が検出され、フレーム時間が跳ねる。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f11","title":"F11イベントループと描画のタイミング 同期処理 → microtask → 描画 → setTimeout","text":"JS は「今の処理が全部終わってから」描画する。だから クラスを外して即付け直しても、間に描画が無いので何も起きない（14・64 の void el.offsetWidth はレイアウトを強制して「外した状態」を確定させる裏技）。順序は：同期コード → microtask（Promise.then, await の続き）→ requestAnimationFrame → 描画 → setTimeout。「描画してから次をやりたい」なら rAF を2回重ねる。 操作：「順序を見る」で各コールバックの実行順をログに出す。「再アニメーション」で、リフロー強制あり／なしの違いを見る。"},{"page":"08-foundations.html","pageTitle":"基礎知識：座標系・イベント・描画の土台","id":"f8","title":"F8混同しやすい用語の対比表 名前が似ている・動きが似ている","text":"「何が違うのか」を一言で。判断の軸は何が動くか／誰が時間を管理するか／どこが原点か。 "},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題1：パンに範囲制限を付ける1","text":"02 パン で、ワールドが枠の外に完全に出てしまわないよう、tx/ty を ±300px に制限する。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題2：ズームの倍率を段階にする1","text":"03 ズーム で、ホイール1回ごとに 25%・50%・100%・200%・400% の5段階だけを行き来するようにする。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題3：トーストを最大3件に制限する1","text":"16 トースト で、4件目が来たら一番古いものを即座に消す。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題4：長押しでコンテキストメニューを出す2","text":"39 コンテキストメニュー を、タッチ端末向けに「500ms の長押し」でも開けるようにする（05 の長押し判定を合成）。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題5：選択にキーボード操作を足す2","text":"11 選択 で、↑↓ で選択を移動、Shift+↑↓ で範囲を伸ばせるようにする。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題6：仮想スクロールの行高を可変にしない代わりに「行の選択」を保つ2","text":"23 仮想スクロール で、行をクリックすると選択状態になり、スクロールして DOM が作り直されても選択が保たれるようにする。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題7：慣性パンにする2","text":"02 パン に 28 慣性 を合成し、離した後も滑って止まるようにする（壁なし、減衰 0.92）。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題8：Undo をインライン編集に接続する2","text":"38 インライン編集 の確定ごとに履歴を積み、Ctrl+Z で表の内容が戻るようにする（37 の方式）。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題9：矩形選択に「ワールド座標」を対応させる3","text":"43 無限キャンバス の上で 48 矩形選択 を動かす。パン・ズームした状態でも、矩形に入ったノードだけ選ばれること。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題10：バッチ操作に「中断」と「再開」を付ける3","text":"76 バッチ操作 に、実行中の「中断」ボタンと、中断位置からの「再開」を追加する（40 の AbortController を合成）。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題11：ドッキングのタブに「閉じる」と「再表示」を付ける3","text":"80 ドッキング で、タブの × でパネルを閉じ、ヘッダーのメニューから閉じたパネルを再表示できるようにする。レイアウト保存にも反映されること。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題12：オフラインキューを楽観的更新と競合解決につなぐ3","text":"57 楽観的更新 の送信を 79 のキュー経由にし、送信時にサーバの revision が進んでいたら 78 の競合ダイアログを出す。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題13：再試行を「見える」ようにする2","text":"122 の再試行に、16 のトーストと進行表示を足す。再試行中は「送信中（再試行 2 回目・あと 1.4 秒）」と出し、最終的に失敗したら 79 のキューへ積む。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題14：Webhook の受け側に「順序の入れ替わり」を足す3","text":"123 の受け口に、版番号が飛んだとき（v3 の次に v5 が来た）を検知して不足分を取りに行く処理を足す。取りこぼしても最終的に正しくなる形にする。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題15：計測に「スナップ」を足す2","text":"136 の 2点間計測で、134 のスナップを使って頂点に吸着させる。面の途中ではなく角を確実に拾えるようにし、吸着したときは印を変える。"},{"page":"09-exercises.html","pageTitle":"練習課題（16問）","id":"","title":"課題16：3Dビューをキーボードだけで操作できるようにする3","text":"132 のピッキングに、マウスを使わない経路を足す。Tab で canvas にフォーカスし、矢印キーで部品を順に選び、Enter で確定、Esc で解除。選択中の部品名を aria-live で読み上げさせる。"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a1","title":"A1キーボードだけで操作できるか フォーカス順の可視化","text":"マウスなしで全機能に届くか。Tab の順番が見た目の順と一致しているか、フォーカスが見えるか、閉じ込められて抜けられない箇所がないか。下のボタンで、このページ内の「フォーカスできる要素」に番号を振って順路を可視化する。 操作：「フォーカス順を表示」→ 番号が見た目の順に並んでいるか確認。その後 Tab で実際に辿る。"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a2","title":"A2読み上げに何が伝わるか アクセシブルネームと role","text":"スクリーンリーダーは「役割（role）」と「名前（accessible name）」を読む。アイコンだけのボタンは名前が空になる。aria-label か視覚的に隠したテキストで名前を与える。下の検査は、ページ内のボタン・リンクで名前が空のものを列挙する。 操作：「名前のない操作要素を探す」。右の例は意図的に名前が無い。"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a3","title":"A3コントラスト比 WCAG 4.5:1（通常文字）/ 3:1（大きな文字・UI部品）","text":"現場の照明や古いモニタでは、薄い灰色の文字は読めない。文字色と背景色から比率を計算し、基準を満たすか確認する。計算式は WCAG の相対輝度。 操作：色を変えて比率を見る。"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a4","title":"A4非同期結果の通知 aria-live の polite / assertive","text":"保存完了やエラーを画面の隅に出しても、読み上げユーザーには伝わらない。aria-live 領域にテキストを書くと自動で読み上げられる。polite は今の読み上げが終わってから、assertive は割り込む（エラー用）。領域は最初から存在させ、中身だけ変える。 操作：ボタンで通知。スクリーンリーダー（Windows: ナレーター Win+Ctrl+Enter、macOS: VoiceOver Cmd+F5）を起動して聞く。"},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a5","title":"A5環境設定の尊重 reduced-motion / contrast / color-scheme / forced-colors","text":"OS の設定をメディアクエリで拾える。動きを減らす、コントラストを上げる、ダークモード、Windows のハイコントラストモード（forced-colors、色指定が無視される）。この環境の現在値を表示する。 "},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a6","title":"A6チェックリストと各デモの対応 実装時に見る","text":" "},{"page":"10-accessibility.html","pageTitle":"アクセシビリティ：キーボード・読み上げ・色・動き","id":"a7","title":"A7canvas と 3D の代替経路 見えない中身をどう伝えるか","text":"&lt;canvas&gt; の中身は支援技術から完全に見えない。画素があるだけで、要素も文字も無いためである。3D ビューア（Z層）・グラフ・図面エディタはすべてこれに当たる。やることは3つ。①canvas 自体をフォーカスできる操作対象にする（tabindex=\"0\" ＋ role ＋ aria-label）②キーボードだけで一巡できるようにする（矢印キーで対象を順に選ぶ）③選択結果や測定値を canvas の外の文字として出す（aria-live）。「見て触る」前提の UI ほど、代替経路を後から足せないので最初に決める。 操作：下の枠を Tab で選び、矢印キーで部品を順に選ぶ。Enter で確定、Esc で解除。読み上げに渡る文字が右に出る。マウスでも同じことができる。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"0. 構成の原則（contextIsolation + preload）","text":"renderer から Node を直接触らせない。preload で必要な関数だけ window.api として公開し、renderer はそれを呼ぶ。これで UI コードはブラウザで動くものと同じになり、デモ・ui-kit がそのまま使える。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"1. ウィンドウ状態の永続化（位置・サイズ・最大化） ← 81 ワークスペース永続化の OS 側","text":"閉じる前に getBounds() を保存し、起動時に復元する。ディスプレイ構成が変わっていると画面外に出るので、screen で表示範囲内か検証してから使う。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"2. フレームレスウィンドウとタイトルバー ← 61","text":"自前タイトルバーは -webkit-app-region: drag。Windows/Linux で OS の最小化・最大化・閉じるボタンだけ残したいなら titleBarOverlay。ダブルクリックで最大化は自前実装。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"3. メニュー・アクセラレータと画面内ショートカットの衝突 ← 62, 35","text":"アプリメニューの accelerator は renderer の keydown より先に取られる。同じキーを両方に登録しない。方針：アプリ全体の操作（新規、保存、終了）はメニュー側、画面内の操作（矢印移動、セル編集）は renderer 側。globalShortcut はアプリが背面でも効くので、業務アプリでは基本使わない。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"4. IPC の型と失敗の扱い ← 57 楽観的更新, 79 オフライン","text":"invoke/handle は Promise を返すので、renderer 側は fetch と同じ感覚で await できる。main で throw した Error は renderer に届く（メッセージのみ）。チャンネル名は '領域:動詞' で統一し、一覧を1ファイルにまとめる。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"5. 複数ウィンドウ ← 85","text":"同一アプリの複数 BrowserWindow は同じオリジンなので、renderer 同士は BroadcastChannel（ui-kit の sync.js）で同期できる。main が「真実の状態」を持つ設計なら、BrowserWindow.getAllWindows() に配信する（62 のコード）。ウィンドウごとに webContents.id を持つので、送信元を除外できる。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"6. ファイルの受け渡し ← 59 ファイルドロップ","text":"OS からのドロップは renderer の drop で受ける（59 と同じ）。パスが必要なら webUtils.getPathForFile(file)（preload 側）。逆にアプリからエクスプローラへドラッグして出すのは webContents.startDrag。保存ダイアログは main の dialog。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"7. 認証情報の保存 ← 13 kintone","text":"API トークンやパスワードを平文の JSON に置かない。safeStorage で OS のキーチェーンに紐づけて暗号化する。renderer には渡さず、main が通信時にだけ復号して使う。外部サービスへのログイン手順（システムブラウザ＋PKCE）は 120、置いてはいけない場所の一覧は 121。現場機器（バーコード・秤・プリンタ）を扱うなら 126：ブラウザ単体では Chromium 系に限られるため、Electron が本命になる。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"8. 表示倍率・DPI ← 55 devicePixelRatio","text":"Ctrl+ホイールの既定ズームは renderer の内容ごと拡大する。図面ビュー（43）で自前ズームをするなら、既定ズームと衝突しないよう wheel で ctrlKey 付きのものを preventDefault するか、webContents.setVisualZoomLevelLimits(1, 1) でピンチズームを止める。Canvas は devicePixelRatio を見て内部解像度を上げる（55）。"},{"page":"12-electron.html","pageTitle":"Electron 実装リファレンス","id":"","title":"9. 二重起動・起動時間・開発者ツール","text":"if (!app.requestSingleInstanceLock()) app.quit(); // 二重起動禁止。2つ目は既存ウィンドウを前面へ app.on('second-instance', () => { const w = BrowserWindow.getAllWindows()[0]; w?.focus(); }); win.once('ready-to-show', () => win.show()); // 白い画面を見せない（show:false で作る） if (!app.isPackaged) win.webContents.openDevTools({ mode: 'detach' }); 10. チェックリスト 項目確認 contextIsolation / sandbox / nodeIntegration:falserenderer から requir"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"0. 呼び出しの置き場所（Electron の場合）","text":"renderer から kintone へ直接 fetch すると、オリジン（file:// や app://）からの CORS で拒否される。main プロセスで通信し、IPC で結果を返す（12 の構成）。トークンも main にだけ置ける。"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"1. 一覧の取得 ← 21 ページネーション / 23 仮想スクロール / 71 大規模グリッド","text":"取得は GET /k/v1/records.json。1回の limit は最大 500、offset は上限あり（大きな値で拒否される）。数千件を超えるならカーソル API（作成→取得を繰り返す）か、$id でソートして「前回の最後の id より大きい」を条件にする方法。取り切ったデータは 23/71 の仮想スクロールで描く（DOM は表示分だけ）。"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"2. 更新とリビジョン ← 57 楽観的更新 / 78 競合解決","text":"レコードは $revision を持つ。PUT 時に revision を付けると、サーバ側が進んでいればエラーで拒否される（省略または -1 で無視）。これが 78 の「楽観ロック」。手順：①開いた時の revision を保持 ②保存時に付けて PUT ③拒否されたら最新を GET して 3方向マージ（ui-kit/merge.js）→ 再 PUT。"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"3. 一括更新 ← 76 バッチ操作","text":"PUT /k/v1/records.json は 1回 最大 100 件（POST 追加・DELETE 削除も同様）。101 件以上は 76 のようにチャンク分割し、チャンクごとに進捗を進める。1回のリクエスト内は全件成功か全件失敗（原子的）なので、「部分失敗」はチャンク単位で起きる。複数種類の操作をまとめて原子的に行いたいときは bulkRequest（1回の中に複数リクエスト、上限あり）。"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"4. 検索 ← 74 検索の型","text":"サーバ検索は query パラメータ（like、in、and/or、order by）。入力のたびに投げないよう 74 のデバウンス（250ms 以上）を入れ、前のリクエストが返る前に次が出たら古い結果を捨てる（連番で判定）。取得済みデータの絞り込みなら手元で ui-kit/search.js。"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"5. オフラインと再送 ← 79","text":"現場端末で通信が切れる前提なら、更新を ui-kit/offline-queue.js に積む。job には app, id, revision, record を入れ、送信時に revision 不一致なら 78 のフローへ回す（課題12）。Electron では main 再起動後もキューが残るよう、storage にファイル保存の実装を渡す。"},{"page":"13-kintone.html","pageTitle":"kintone 連携リファレンス","id":"","title":"6. フィールド型と UI 部品の対応 kintone フィールド値の形向く UI（番号） 文字列（1行）／数値{ value: '…' }38 インライン編集、56 グリッド ドロップダウン／ラジオ{ value: '選択肢' }20 ドロップダウン、36 コマンドパレット（選択肢が多い時） チェックボックス／複数選択{ value: ['a','b'] }11 選択（Ctrl/Shift） 日付／日時'2026-09-12' / ISO 860184 タイムライン、75 フォーム ユーザー選択{ value: [{ code, name }] }74 あいまい検索つき選択 テーブル（サブテーブル）{ value: [{ id, value: {…} }] }56 グリッド、32 並べ替え 添付ファイル{ value: [{ fileKey, name }] }59 ファイルドロップ → アップロード API → fileKey を付けて PUT 関連レコード／ルックアップ参照先の値83 スマートプレビュー（ホバーで参照先を先読み） $id / $revisionシステム値78 競合解決、82 ルーティング（URL に id） 7. 上限の早見表（要公式確認） 操作上限（把握値）UI 側の対応 GET records の limit500 件/回21 ページング、23 仮想スクロール GET records の offset上限あり（大きい値は拒否）id 基準取得かカーソル API POST / PUT / DELETE records100 件/回76 チャンク分割と進捗 bulkRequest複数リクエストを1回で原子的に（件数上限あり）76 の「全部成功か全部失敗」が必要な時 同時リクエスト数ドメインごとに上限あり並列度を絞る（76 の Promise.all は数件まで）。上限に当たったときの再試行は 122 query の文字列長／like上限あり。前方一致のみ等の制約74 で手元検索と併用 8. kintone カスタマイズ JS の中で使う場合（Electron ではなく kintone 画面内）","text":"kintone の画面に JS を読み込ませるカスタマイズでは、通信は kintone.api()（CORS も認証も不要）、画面の差し込み先は kintone.app.getHeaderSpaceElement() 等。デモと ui-kit はそのまま使えるが、kintone 側の DOM は書き換えない（アップデートで壊れる）。自前の要素をスペースに追加し、その中で動かす。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n87","title":"87親を選ぶ :has()","text":"CSS は長く「子は選べるが親は選べない」制約があり、状態を親要素のクラスとして JS で付け外ししていた。:has() は「その中に◯◯を含む要素」を選べるので、状態の管理を CSS に寄せられる。行の選択、入力の有無、エラーの有無、画像付きカードの出し分けなど。 操作：チェックを入れる／入力する。JS は一行も動いていない。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n88","title":"88出入りのアニメーション @starting-style / transition-behavior: allow-discrete","text":"display: none の要素は「表示した瞬間の初期値」が無いためアニメーションできず、12 のように opacity だけで消す（要素は残る）か、JS で二段階に切り替えていた。@starting-style が出現時の初期値を与え、transition-behavior: allow-discrete が display の切り替えを遷移の最後まで遅らせるので、出入り両方が CSS だけで書ける。 操作：トグル。閉じるときも最後まで見えている（display の切替が遅延される）。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n89","title":"89ポップオーバー popover 属性 / popovertarget","text":"20（ドロップダウン）と 17（ツールチップ）で自前実装した「外側クリックで閉じる」「Esc で閉じる」「最前面に出す」が、popover 属性だけで手に入る。トップレイヤーに出るので F7 のスタッキングコンテキスト問題（親の transform で埋もれる）も起きない。 操作：ボタンで開き、外側クリックか Esc で閉じる。JS なし。親に transform が掛かっていても最前面に出る。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n90","title":"90アンカー位置指定 anchor-name / position-area / position-try-fallbacks","text":"17 では getBoundingClientRect() で座標を測り、画面端では反転させる処理を JS で書いた。anchor-name で「基準の要素」に名前を付け、position-area でどちら側に置くかを宣言し、position-try-fallbacks で「入らなければ反対側」を指定すれば、位置決めのコードが全部消える。スクロールしても追従する。 操作：枠を横スクロールして端のボタンを押す。はみ出す側では自動で反対側に出る。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n91","title":"91height: auto へのアニメーション interpolate-size / calc-size()","text":"18（アコーディオン）で触れた「height: auto にはトランジションが効かない」という長年の壁。interpolate-size: allow-keywords を指定すると auto や min-content への遷移が補間できるようになり、grid の 0fr→1fr という回避策も、JS で scrollHeight を測る処理も要らなくなる。 操作：開閉する。中身の長さが違っても、高さを測らずに滑らかに開く。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n92","title":"92排他アコーディオン details name / ::details-content","text":"「1つ開いたら他は閉じる」を JS で管理していたが、&lt;details name=\"同じ名前\"&gt; にするだけでラジオボタンのように排他になる。::details-content で中身を直接スタイルでき、91 と組み合わせれば開閉アニメーションも CSS だけで済む。 操作：見出しをクリック。他が自動で閉じる。JS なし。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n93","title":"93入力欄の自動伸長 field-sizing: content","text":"テキストエリアを内容に合わせて伸ばすために、scrollHeight を読んで style.height を書く処理（F9 のレイアウトスラッシングの温床）を書いていた。field-sizing: content で不要になる。備考欄が多い業務フォームで効く。 操作：打ち込むと欄が伸びる。min-height / max-height で範囲を決められる。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n94","title":"94画面外の描画を省く content-visibility: auto / contain-intrinsic-size","text":"23 の仮想スクロールは「DOM を作らない」方式で最速だが、実装コストが高い。content-visibility: auto はDOM は置いたまま、画面外の描画とレイアウトだけを省く。contain-intrinsic-size で仮の大きさを教えるとスクロールバーも安定する。数百〜数千行なら実装ゼロでこれで足りることが多い。 操作：切り替えて描画時間を比べる（1,000 行）。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n95","title":"95テーマと色の計算 light-dark() / color-mix() / oklch()","text":"70 のテーマ切替は「ライト用とダーク用の変数を2セット書く」形だった。light-dark() は1行で両方を書ける。color-mix() は基準色1つから、ホバー・無効・枠線の色を自動で作れるので、配色の定義が減る。oklch() は明度が知覚とほぼ一致するため、混ぜても濁りにくい。 操作：基準色とテーマを変える。派生色は全て計算で作られる。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n96","title":"96状態を保ったまま移動する Element.moveBefore()","text":"32 の並べ替えは insertBefore で DOM を動かす。これは「一度取り外して付け直す」動作なので、iframe は再読み込みされ、フォーカスや再生中の動画・アニメーション・popover の開閉状態が失われる。moveBefore() は接続を保ったまま移動するため、状態が壊れない。グリッド内の埋め込み表示や入力途中の行を動かす場面で効く。 操作：それぞれの「先頭へ」を押す。左（従来）はカウンタが 0 に戻り、右（moveBefore）は数え続ける。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n97","title":"97DOM を変えずに強調する CSS Custom Highlight API","text":"74 の検索ハイライトは一致部分を &lt;mark&gt; で囲むため、DOM を作り直す＝選択・フォーカス・イベントの結び付きが切れる。Custom Highlight API は文字範囲（Range）に名前を付けて色を塗るだけなので、DOM は一切変わらない。大量の一致でも軽い。 操作：検索語を入れる。文章の DOM は変わらないまま色が付く（開発者ツールで確認できる）。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n98","title":"98長い処理で UI を止めない scheduler.yield() / long-animation-frame","text":"54 は「描画をまとめる」話だったが、逆に重い計算そのものが長すぎると、その間クリックもスクロールも効かなくなる（F10 の longtask）。await scheduler.yield() を挟むと、その場でブラウザに順番を譲り、続きは優先的に再開される（setTimeout(0) より順番待ちが短い）。CSV 変換や一括計算はこれで分割する。 操作：3方式を試す。左の丸が回り続けるかを見る。総時間はどれもほぼ同じで、違うのは「途中で画面が動くか」だけ。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n99","title":"99業務コードが短くなる標準API Object.groupBy / toSorted / Promise.withResolvers / AbortSignal.any / Intl","text":"集計・並べ替え・非同期・書式で、自前のユーティリティを書かずに済むようになったもの。元の配列を壊さない（toSorted）、グループ化が1行（Object.groupBy）、外から解決できる Promise（withResolvers：ダイアログの戻り値待ちに最適）、複数の中断条件を束ねる（AbortSignal.any：タイムアウト＋ユーザー中断）。 操作：実行して結果を見る。コードを開いて書き方を確認する。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n100","title":"100カルーセルの操作部品 ::scroll-button() / ::scroll-marker","text":"25 のスクロールスナップに「前後ボタン」と「現在位置のドット」を付けるには JS が必要だった。::scroll-button() と ::scroll-marker はスクロール領域そのものから疑似要素として生やせる。押せない端では自動で :disabled になり、現在位置のマーカーには :target-current が付く。キーボード操作も付いてくる。 操作：◀▶ とドットで移動する。JS なし。"},{"page":"17-modern.html","pageTitle":"第5弾 M：最近できるようになったこと（87〜101）","id":"n101","title":"101並び順を CSS から使う sibling-index() / sibling-count()","text":"64 のスタガーは「何番目か」を style=\"--i:3\" と HTML に書くか JS で付けていた。sibling-index() はCSS が自分で順番を知るので、要素を増減しても何も直さなくてよい。遅延だけでなく、色や大きさの段階付けにも使える。 操作：「行を足す」→「再生」。足した行にも自動で正しい遅延が付く。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n102","title":"102この端末は何か 実測パネル","text":"まずは自分が今いる環境を知る。以下はすべてブラウザが答えた実際の値。現場で使う端末でこのページを開き、値を控えておくと、以降の判断（当たり判定の大きさ、ホバーの可否、使える API）が全部決まる。 操作：ウィンドウの大きさを変える、タッチで触る、と値が変わる項目がある。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n103","title":"103入力装置と当たり判定 pointer / any-pointer / 44px","text":"マウスは 1px を狙えるが、指は狙えない。@media (pointer: coarse) で見た目を変えずに当たり判定だけ広げるのが定石（::before を伸ばす）。指で使う画面は 44×44px 以上が目安。タッチとマウスの両方が繋がる端末（現場のタブレット＋マウス）もあるので、`any-pointer` で「どちらも来る」前提にする。 操作：下の2つのボタンの周囲（薄い枠）が実際の当たり判定。coarse の端末では自動で広がる。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n104","title":"104修飾キーの差 Ctrl / ⌘ / Alt / Option","text":"Windows の Ctrl は macOS の ⌘（metaKey）。判定を間違えると Mac で全く効かない。画面に出す表記も OS で変える（Mac に「Ctrl+S」と出ていると迷う）。navigator.userAgentData.platform で判定し、無い環境では navigator.platform にフォールバックする。 操作：キーを押す。押された修飾キーと、この OS での正しい表記が出る。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n105","title":"105画面の高さ vh / svh / lvh / dvh","text":"スマートフォンではスクロールに応じてアドレスバーが伸縮するため、100vh は「バーが隠れたときの高さ」＝画面より大きく、下がはみ出す。svh（最小＝バーが出ている状態）、lvh（最大）、dvh（今の実際の高さ、変化に追従）で正確に指定できる。全画面のパネルやモーダルは dvh か svh。 操作：スマートフォンで開いてスクロールすると差が出る。下の帯は同じ「10%」の高さを4種類の単位で描いたもの。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n106","title":"106セーフエリア env(safe-area-inset-*) / viewport-fit=cover","text":"ノッチ、ホームバー、丸い角のある端末では、画面の端に置いた操作部品が隠れる・押せない。&lt;meta name=\"viewport\" content=\"…, viewport-fit=cover\"&gt; を付けたうえで env(safe-area-inset-bottom) などを余白に足す。固定ヘッダー・固定フッター・全画面モーダルの3か所で必ず要る。 操作：該当端末では下の帯に余白が入る。この端末の実測値は下に表示される。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n107","title":"107日本語入力（IME）の途中を無視する compositionstart / isComposing","text":"この資料で最も実害が出やすい項目。日本語を打つと、変換確定前の「かな」の段階でも input と keydown が飛ぶ。対策しないと、①検索が「けん」「けんさ」…と無駄に走る ②Enter による変換確定を「決定」と誤認して、確定した瞬間にフォームが送信される、が起きる。event.isComposing（または compositionstart/end）で変換中は無視するのが正解。 操作：日本語入力に切り替えて「けんさ」と打ち、変換して Enter。左（対策なし）は途中で何度も反応し、Enter を確定として扱ってしまう。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n108","title":"108「戻る」で閉じる CloseWatcher / Android のバックキー","text":"Android では戻る操作でモーダルを閉じるのが期待される挙動。従来は履歴に push して popstate で閉じる小細工が要った。CloseWatcher は「Esc・Android の戻る・ブラウザの戻るジェスチャー」をまとめて1つのイベントで受け取れる。&lt;dialog&gt; と popover は最初からこの挙動を持つ（自前のオーバーレイにだけ必要）。 操作：開いて Esc（Android なら戻るキー）で閉じる。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n109","title":"109スクロールバーの差 scrollbar-gutter / scrollbar-width / overscroll-behavior","text":"Windows のスクロールバーは場所を取る（出た瞬間に中身が 15px ずれる）。macOS と iOS は重なって表示され消える。scrollbar-gutter: stable で最初から場所を空けておくとズレが起きない。overscroll-behavior: contain は「内側を末端まで送ったら親までスクロールが伝わる」現象（モーダル内スクロールの定番の不快さ）を止める。 操作：3つの枠をスクロールする。中央は末端でも親に伝わらない。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n110","title":"110タッチ端末の癖 touch-action / tap highlight / 自動ズーム","text":"タッチ特有の4つ。①ダブルタップズームで連打が拾われない ②タップ時に灰色の矩形が光る ③iOS は 16px 未満の入力欄で自動的に拡大する（現場で一番嫌われる） ④長押しで選択・コンテキストメニューが出る。いずれも CSS で抑えられるが、抑えすぎると選択やコピーができなくなるので、対象は操作部品に限る。 操作：タッチ端末で2つの領域を触り比べる。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n111","title":"111日本語のテキスト処理 text-wrap / word-break / Intl.Segmenter","text":"日本語は単語の区切りが無いので、意味の切れ目を無視して折り返される。text-wrap: balance（見出しの行長を揃える）、pretty（最終行に1文字だけ残さない）、word-break: auto-phrase（文節で折る）で読みやすくなる。省略は text-overflow: ellipsis、文字数の数え方は絵文字や結合文字があるため Intl.Segmenter が正確（.length は誤る）。 操作：幅を変えて折り返しの違いを見る。下は文字数の数え方の比較。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n112","title":"112印刷 @page / break-inside / print-color-adjust","text":"現場では画面より紙が正義のことがある。@media print で操作部品を消し、@page で余白と向きを決め、break-inside: avoid で表の行が分断されるのを防ぐ。背景色は既定で印刷されないので、色で状態を示している表は print-color-adjust: exact を指定するか、記号を併記する（10 のチェックリストと同じ理由）。 操作：「印刷プレビュー」で確認（このデモの領域だけが印刷対象になるよう指定してある）。"},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n113","title":"113機能検出と段階的強化 @supports / CSS.supports / 'x' in y","text":"17 章の新機能を業務アプリで使う判断は「無くても仕事が終わるか」で決める。@supports で対応環境だけ上書きする書き方にすれば、非対応環境には従来の実装が残る。JS は 'moveBefore' in Element.prototype のように使う直前に確かめる。下の表はこの端末の実測。 "},{"page":"18-crossplatform.html","pageTitle":"第5弾 X：クロスプラットフォーム（102〜113）","id":"n113b","title":"◎実行環境ごとの早見表 ブラウザ / Electron / kintone / 現場タブレット","text":" "},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n114","title":"114連携方式の選び方 4つの型","text":"最初の分岐がその後の難易度をほぼ決める。①埋め込み（iframe）＝相手の画面をそのまま出す。作るものが最も少ないが、認証とストレージ分断（117）で詰まる。②直接呼ぶ（ブラウザから API）＝速いが CORS（118）と鍵の秘匿（121）が問題。③サーバ経由＝一番自由で安全だが、置き場所が要る。④ネイティブ橋渡し（Electron）＝CORS も鍵も解決するが、配布物が要る。 "},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n115","title":"115iframe と postMessage 相互通信実動","text":"埋め込んだ画面とやりとりする唯一の手段。要点は3つ。①送信時に targetOrigin を必ず具体的に書く（'*' は誰にでも届く）②受信時に event.origin を必ず検証する（誰でも送れる）③相手の準備完了を待つ握手をする（読み込み前に送ると消える）。高さの自動調整も postMessage で送るのが定番。 操作：下の枠は別文書。ボタンで双方向に送る。ログに origin 検証の結果が出る。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n116","title":"116埋め込まれる側の作法 sandbox / frame-ancestors実動","text":"自分の画面が他人のページに埋め込まれる場合の防御と、他人の画面を埋め込む場合の制限。埋め込む側は sandbox 属性で権限を絞る（スクリプト・フォーム送信・別窓・トップレベル遷移などを個別に許可）。埋め込まれる側は Content-Security-Policy: frame-ancestors で誰に埋め込ませるかを決める（クリックジャッキング対策）。 操作：sandbox の指定を変えて、中のスクリプトが動くかどうかを見る。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n117","title":"117埋め込みでログインが切れる 3rd party Cookie / CHIPS / Storage Access API模擬","text":"「PC では見えるのに、iPhone だと iframe の中がログイン画面になる」の原因。ブラウザは埋め込まれた別サイトの Cookie を、トップレベルのサイトごとに分離する。2026年時点の状況：Chrome は 3rd party Cookie の廃止を撤回して継続、Safari・Firefox はブロックを継続。つまり環境によって挙動が違う状態が続く。対処は3つ：CHIPS（Cookie に Partitioned を付け、トップレベルごとに別の入れ物として持つ）、Storage Access API（ユーザー操作を起点に許可を求める）、そしてそもそも iframe をやめる（114 の③④）。 操作：この端末の判定と、3方式の比較を表示する。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n118","title":"118CORS とプリフライト なぜ「サーバ経由」が要るのか模擬","text":"ブラウザは別オリジンへの読み取りを既定で禁じる。許可を出すのは相手のサーバであって、こちら側では変えられない。Content-Type: application/json や独自ヘッダを付けると事前確認（プリフライト）の OPTIONS が先に飛び、相手がそれに答えないと本体は送られない。認証情報を送るなら credentials と Access-Control-Allow-Credentials の両方が必要で、ワイルドカードは使えない。相手が対応していなければ 114 の③（サーバ経由）しか手がない。 操作：要求の条件を変えて、通るか・プリフライトが要るかを判定する（相手のサーバ設定は下で切り替える）。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n119","title":"119OAuth 2.1 と PKCE 認可コード + PKCE（S256）実動","text":"2026年の標準形。OAuth 2.1 では PKCE が必須で、implicit フロー（トークンを URL で受け取る）は廃止。仕組み：①ランダムな code_verifier を作り ②その SHA-256（code_challenge）だけを認可画面へ渡す ③戻ってきた認可コードと verifier を一緒に送る。途中でコードを盗まれても、verifier を知らなければトークンに交換できない。アクセストークンはメモリに置く（localStorage は XSS で読まれる）。リフレッシュトークンは自前サーバからの HttpOnly Cookie にする。 操作：実際に WebCrypto で verifier / challenge を生成し、模擬の認可サーバとやりとりする。攻撃者がコードだけ盗んだ場合も試せる。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n120","title":"120Electron での認証 システムブラウザ + safeStorage模擬","text":"デスクトップアプリではアプリ内に認証画面を埋め込まないのが原則（利用者が本物のドメインを確認できないため、相手のサービスに拒否されることも多い）。システムブラウザを開き、ループバック（http://127.0.0.1:port）かディープリンク（myapp://）で戻す。トークンは safeStorage で OS の鍵に紐づけて暗号化し、renderer には渡さない（12 の構成）。 "},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n121","title":"121鍵を画面に置かない クライアントに秘密は無い実動","text":"ブラウザや renderer に置いた値は、すべて利用者に読める。難読化しても変わらない。「API キーを JS に埋める」「kintone のカスタマイズに管理者トークンを書く」は、その画面を開ける全員にキーを配るのと同じ。鍵が要る呼び出しは 114 の③④（サーバ／main 経由）に寄せる。 操作：下のボタンで、このページの JS に「隠した」つもりの値を取り出す。実際には数行で読める。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n122","title":"122レート制限と再試行 429・バックオフ・冪等キー実動","text":"外部 API は必ず絞られる（kintone も 1 アプリあたりの同時実行数・秒間リクエスト数に上限がある。具体的な数値は相手の仕様書で確認すること＝ここでは断定しない）。上限に当たると 429 Too Many Requests が返り、多くは Retry-After ヘッダで「何秒待て」と教えてくる。やることは3つ。①すぐ再試行しない（待ち時間を倍々にする＝指数バックオフ）②ジッター（ゆらぎ）を足す（全端末が同時に再開すると再び詰まる＝雪崩）③冪等キーを付ける（送信は成功したが応答が届かなかったとき、二重登録を防ぐ）。 操作：同じ模擬 API（先頭2件しか通らない）に 6 件送る。3つの方式で結果と所要時間を比べる。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n123","title":"123Webhook の受け側 署名検証・リプレイ・冪等実動","text":"相手のサービスから「起きたこと」を押し込んでもらう仕組み。受け口は誰でも叩ける URL なので、次の3つが必須。①署名検証（本文と共有鍵の HMAC が一致するか。ここは WebCrypto で実際に計算する）②時刻の確認（古い正しい署名の使い回し＝リプレイを弾く）③冪等処理（相手は「届いたか不明」なら再送する。同じイベント ID を二度処理しない）。さらに順序は保証されない前提で、イベント内の版番号や更新時刻で新旧を判断する。 操作：正しい配送・改ざん・古い時刻・再送を送り分け、受け口の判定を見る。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n124","title":"124反映方式の選び方 ポーリング／SSE／WebSocket実動","text":"「他の人の更新をどう画面に出すか」の3択。ポーリング＝一定間隔で問い合わせる。最も簡単で、どんな相手にも使える（kintone のように Webhook しか無い相手でも成立）。SSE（EventSource）＝サーバから一方向に流し続ける。実装が軽く自動再接続つき。WebSocket＝双方向。カーソル共有や共同編集はこれが要る。迷ったらポーリングから始め、遅延と無駄が問題になってから上げる。 操作：同じ「サーバの値」を3方式で追う。無駄な通信回数と、変化を検知するまでの遅れを比べる。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n125","title":"125ファイルの授受 保存・読込・貼り付け・共有実動","text":"現場の連携は「ファイルを渡す・受け取る」で足りることが多い。ダウンロード／&lt;input type=file&gt; はどこでも動く最終手段。File System Access API（showSaveFilePicker / showOpenFilePicker）は同じファイルに上書き保存できる＝「編集して保存」が成立する（Chromium 系のみ）。クリップボードは写真や図の受け取りに効く。Web Share は主にモバイルで、他アプリへ渡す。 操作：この環境の対応状況を実測。保存 → 読込 → 貼り付けを試す。file:// では一部が使えないことがある。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n126","title":"126現場機器との連携 WebHID・WebSerial・WebUSB実動","text":"バーコードリーダー・電子秤・ノギス・ラベルプリンタをブラウザから直接扱う API 群。すべて Chromium 系のみ（Safari・Firefox は方針として非対応。2026 年時点の利用可能な利用者はおよそ 4 分の 1 前後にとどまる＝正確な比率は caniuse 等で都度確認）。したがって現場配布では Electron が本命：Chromium を同梱するので API がそのまま使え、さらに Node の serialport 等も使える。バーコードリーダーの多くはキーボードとして振る舞うので、まず「フォーカスした入力欄に高速入力される」前提で作れば API は不要（下で実測できる）。 操作：対応状況を実測。接続ボタンは実機がある環境でのみ完走する（無い場合はデバイス選択が空になる）。下の欄はリーダーを繋がなくても「速い連続入力」で判定を確かめられる。"},{"page":"20-integration.html","pageTitle":"第6弾 Y：サードパーティ連携（114〜127）","id":"n127","title":"127埋め込みウィジェットを作る側 Shadow DOM で壊れない部品実動","text":"自分が作った部品を他人のページに貼ってもらうとき、相手の CSS がこちらを壊し、こちらの CSS が相手を壊す。attachShadow で影の木を作れば、スタイルが両方向に漏れない。ページ側の * { box-sizing } も button { } も届かない。kintone のカスタマイズやポータルへの部品配布はこの形が正解。 操作：「乱暴な CSS」を有効にすると、通常の部品は崩れ、Shadow DOM の部品は無傷なことが分かる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n128","title":"1283Dの座標系と行列 モデル → ワールド → ビュー → クリップ → 画面","text":"43 の toWorld / toScreen の 3D 版。ある点は5つの座標系を順に通って画面に着く。①モデル座標（部品の中の位置）②ワールド座標（置いた場所）③ビュー座標（カメラから見た位置）④クリップ座標（投影後）⑤画面座標（px）。3Dのバグの大半は「今どの座標系の値を触っているか」の取り違えで起きる。 操作：ドラッグでカメラを回すと、青い部品の角の点が各座標系でどう変わるかが表で追える。ワールド座標は動かず、ビュー以降だけが変わることを確認する。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n129","title":"129カメラ操作 オービット / パン / ドリー","text":"3D ビューアの共通作法。オービット＝注視点を中心に回り込む、パン＝注視点ごと平行移動、ドリー（ズーム）＝注視点との距離を変える。02 のパンと 03 のズームの立体版で、動いているのは物体ではなくカメラという点が違う。真上・真下で回り込みが破綻しないよう仰角に上限を設けるのが定石。 操作：ドラッグ＝オービット、Shift+ドラッグ（または2本指）＝パン、ホイール／ピンチ＝ドリー。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n130","title":"130ビューキューブと投影方式 正面・上面へのスナップ / 正投影と透視","text":"CAD 系ビューアの右上にある立方体。今どちらを向いているかを示し、面や軸をクリックするとその向きへスナップする。図面的な確認には正投影（奥行きで大きさが変わらない＝寸法が読める）、全体像の把握には透視投影を使い分ける。 操作：ボタンで視点をスナップ。投影方式を切り替えると、奥の部品の大きさの見え方が変わる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n131","title":"131WebGPU と WebGL2 2026年1月に WebGPU が Baseline","text":"ブラウザで 3D を描く API は 2つ。WebGL2 はどこでも動く枯れた選択肢、WebGPU は 2026年1月に主要ブラウザで Baseline に到達した新しい API で、描画コールの束ね方が効率的なうえ計算（コンピュートシェーダ）が使える。業務アプリでの現実解は 113 と同じ段階的強化：WebGPU があれば使い、無ければ WebGL2。このページのデモは WebGL2 で動いている。 操作：この端末の対応状況とアダプタ情報を表示する。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n132","title":"132ピッキング レイキャスト と カラーIDバッファ","text":"「クリックした先にどの部品があるか」を求める操作。2方式ある。レイキャスト＝画面の点から光線を飛ばし、三角形との交差を CPU で計算する（当たった位置と法線まで分かるので計測に使える）。カラーIDバッファ＝各部品を「連番を色にして」描き、1px 読む（三角形数が増えても遅くならない代わりに、GPU の描画完了を待つ readPixels の同期待ちが毎回入る。位置も分からない）。部品数が少ないうちはレイキャストの方が速く、モデルが重くなるほどカラーIDが有利になる。55 の Canvas ヒットテストの 3D 版。 操作：部品をクリック。方式を切り替えて、所要時間と得られる情報の差を見る。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n133","title":"133変形ギズモ 軸ハンドルで動かす","text":"選んだ部品を動かす取っ手。要点は3つ。①軸に拘束する（X ハンドルを掴んだら X しか動かない＝51 の軸固定の 3D 版）②画面上で一定の大きさに見えるようカメラ距離に比例させる（遠くの部品でも掴める）③掴んでいる間はカメラ操作を止める（52 の状態機械）。ドラッグ量は軸を含みカメラに正対する平面との交点から求める。 操作：部品をクリックで選択 → 赤(X)・緑(Y)・青(Z) の棒をドラッグ。Shift で 0.25 刻みに吸着（134）。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n134","title":"134スナップ グリッド / 面 / 角度","text":"47 のスナップの 3D 版。位置の刻み（グリッド）、他の部品の面に載せる、角度の刻み（15°など）。判定は 47 と同じ「候補を列挙し、しきい値内で最も近いものに吸着」。3D では吸着したことを画面で示す（ガイド線・色変化）のがより重要で、見た目だけでは合っているか分からない。 操作：スライダで部品を動かす。刻みを切り替えると、値が丸められる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n135","title":"135選択の可視化 強調・半透明・複数選択","text":"11 の選択の 3D 版。3D では選んだ物が他の部品の裏に隠れるため、色を変えるだけでは足りない。実務では①選択部品を強調色にする ②それ以外を半透明にする（中身が見える）③輪郭線を描く、のいずれかを使う。Ctrl/⌘ で追加選択するのは 11 と同じ作法。 操作：部品をクリック。Ctrl/⌘+クリックで追加。表示方式を切り替える。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n136","title":"136計測 2点間の距離","text":"現場で最もよく使われる 3D 機能。132 のレイキャストが「当たった位置」を返すので、2点取れば距離が出る。実装で外せないのは①どの点を取ったかを 3D 上に示す ②寸法線と数値を2D のラベルとして重ねる（139 と同じ仕組み）③単位と丸めを明示する（モデルの 1.0 が 1m なのか 1mm なのかは形式とデータ次第で、glTF は m が既定）。 操作：部品の面を2か所クリック。距離が出る。「やり直す」で消える。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n137","title":"137断面 クリッピング平面","text":"組立の内部や、部品同士の干渉を見るために手前を切り落とす。実装は簡単で、フラグメントシェーダで「平面の表側にある画素を捨てる」だけ（discard）。注意点は切り口が開いて見えること。中身が詰まって見える「キャップ」を作るには、裏面だけを別に描くなどの追加処理が要る。 操作：軸とスライダで切る位置を変える。キャップの有無で見え方の違いを比べる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n138","title":"138分解図と組立手順 Exploded view","text":"部品を中心から離して、重なりを解いて見せる。作業手順書では段階的に離す／1部品ずつ順に出すことで組立順を示す。実装は「各部品に離す方向を持たせ、係数 t を 0→1 に動かす」だけ。順に出す演出は 64 のスタガーと同じで、t を部品ごとに遅らせる。 操作：スライダで分解、「手順を再生」で順に組み上がる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n139","title":"139注釈・ホットスポット 3D 座標に貼り付くラベル","text":"17 のツールチップの 3D 版。ラベルは DOM 要素のままにして、project() で 3D 座標を画面座標に変換して毎フレーム位置を合わせるのが定石（文字は DOM の方が読みやすく、選択もできる）。要点は裏側に回ったら薄くする／隠すこと。厳密には「そのラベル位置がカメラから見えているか」をレイキャストで判定する（遮蔽判定）。 操作：カメラを回すと、部品の裏に回ったラベルが薄くなる。ラベルをクリックすると内容が出る。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n140","title":"140モデルの読み込みと変換 glTF / GLB と、CAD 形式からの変換","text":"Web の 3D の標準は glTF（.gltf / .glb）で、「3D の JPEG」と呼ばれる転送用の形式。製造業で手元にあるのは STEP・IGES・IFC・DWGだが、これらはブラウザで直接は開けず事前の変換が要る（IFC は web-ifc、STEP は OpenCascade 系のツールで変換するのが定番）。設計データをそのまま配らず「表示用に変換したもの」を配るのは、容量と機密の両面で正しい。 操作：下の箱を glTF に書き出し、それを読み込み直して表示する（JSON の中身も見える）。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n141","title":"141大規模モデルの性能 描画コールとフレーム時間","text":"54・F9・F10 の 3D 版。3D で最初に効くのは描画コールの数（部品ごとに1回 GPU に命令すると、部品数がそのままコストになる）。対策は①同じ形はまとめて一度に描く（インスタンス化）②画面外を描かない（カリング）③遠くは粗いモデルに差し替える（LOD）。現場のタブレットは GPU が弱いので、必ず実機で測る。 操作：部品数を変えてフレーム時間を見る。数百を超えると描画コールが効いてくる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n142","title":"142AR で現物と重ねる WebXR / Scene Viewer / Quick Look","text":"現場で「図面の部品が、実際にその場所へ収まるか」を確かめる使い方。Web の AR は単一の API ではなく、端末ごとに別の仕組みへ橋渡しするのが実情：Android は WebXR（ブラウザ内でそのまま）か Scene Viewer（OS のアプリへ渡す）、iOS は Quick Look（.usdz を OS に渡す）。&lt;model-viewer&gt; はこの3つを自動で切り替える。glTF と USDZ の2形式を用意する必要がある点が実務上の最大の注意。 操作：この端末で AR が使えるかを判定する。現場のスマートフォン・タブレットで開くと結果が変わる。"},{"page":"21-3d.html","pageTitle":"第6弾 Z：3Dの操作と編集（128〜143）","id":"n143","title":"143ライブラリ選定と依存方針 自前 / three.js / model-viewer / web-ifc","text":"ここまでのデモは依存なしの約 350 行で動いている。これは「中で何が起きているか」を見せるためであり、実務では目的に合うものを選ぶ。判断軸はやりたいことの範囲・配布サイズ・オフライン動作・保守の担い手。業務アプリでは「表示と計測だけ」なら &lt;model-viewer&gt; で足り、編集が要るなら three.js、建築・設備なら web-ifc、という切り分けになる。 "}];
